def main(data) -> dict:
    import json

    try:
        if isinstance(data, dict):
            obj = data
        elif isinstance(data, str):
            text = data.strip()
            if not text:
                raise ValueError("data为空")
            obj = json.loads(text)
        else:
            raise TypeError("data必须是JSON字符串或Object")

        if not isinstance(obj, dict):
            raise TypeError("data解析结果必须是Object")

        return {
            "parsed_data": obj,
            "parse_ok": True,
            "parse_err": ""
        }
    except Exception as exc:
        return {
            "parsed_data": {},
            "parse_ok": False,
            "parse_err": str(exc)
        }

def main(parsed_data: dict) -> dict:
    errors = []
    warnings = []
    checks = []

    required_groups = [
        "任务信息", "运行图计划参数", "分时段计划参数",
        "车辆及折返计划", "首末班车计划", "业务系统直接指标",
        "列次执行异常明细", "分时段执行指标", "断面满载率明细",
        "换乘衔接指标", "换乘失配明细", "重点末班换乘失配明细",
        "首末班车执行明细", "运营边缘时段指标", "外部交通衔接指标"
    ]
    for name in required_groups:
        if name not in parsed_data:
            errors.append(f"缺少顶层数据组：{name}")

    if errors:
        return {
            "is_valid": False,
            "error_list": errors,
            "warn_list": warnings,
            "check_list": checks
        }

    task = parsed_data.get("任务信息", {})
    for field in ["评估日期", "线路编码", "线路名称", "运行图编号", "运行图版本"]:
        if not task.get(field):
            errors.append(f"任务信息.{field}不能为空")

    expected_periods = {"早高峰", "晚高峰", "平峰", "低谷"}
    plan_periods = [x.get("时段类型") for x in parsed_data.get("分时段计划参数", [])]
    exec_periods = [x.get("时段类型") for x in parsed_data.get("分时段执行指标", [])]

    if set(plan_periods) != expected_periods or len(plan_periods) != 4:
        errors.append("分时段计划参数必须且只能包含早高峰、晚高峰、平峰、低谷")
    if set(exec_periods) != expected_periods or len(exec_periods) != 4:
        errors.append("分时段执行指标必须且只能包含早高峰、晚高峰、平峰、低谷")

    plan = parsed_data.get("运行图计划参数", {})
    direct = parsed_data.get("业务系统直接指标", {})

    numeric_nonnegative = [
        ("运行图计划参数.计划开行列次", plan.get("计划开行列次")),
        ("运行图计划参数.计划车辆总数", plan.get("计划车辆总数")),
        ("运行图计划参数.备用车数", plan.get("备用车数")),
        ("业务系统直接指标.计划兑现列次", direct.get("计划兑现列次")),
        ("业务系统直接指标.实际开行列次", direct.get("实际开行列次")),
        ("业务系统直接指标.停运列次", direct.get("停运列次")),
        ("业务系统直接指标.加开列次", direct.get("加开列次")),
        ("业务系统直接指标.晚点列次", direct.get("晚点列次"))
    ]
    for name, value in numeric_nonnegative:
        if not isinstance(value, (int, float)) or value < 0:
            errors.append(f"{name}必须是非负数")

    ratio_fields = [
        ("运行计划达成率", direct.get("运行计划达成率")),
        ("运行准点率", direct.get("运行准点率")),
        ("全日平均满载率", direct.get("全日平均满载率"))
    ]
    for item in parsed_data.get("分时段执行指标", []):
        period = item.get("时段类型", "未知")
        ratio_fields.extend([
            (f"{period}.上线兑现率", item.get("上线兑现率")),
            (f"{period}.最大满载率", item.get("最大满载率")),
            (f"{period}.平均满载率", item.get("平均满载率"))
        ])
    ratio_fields.extend([
        ("换乘衔接成功率", parsed_data["换乘衔接指标"].get("换乘衔接成功率")),
        ("末班换乘保障率", parsed_data["换乘衔接指标"].get("末班换乘保障率")),
        ("交通衔接覆盖率", parsed_data["外部交通衔接指标"].get("交通衔接覆盖率"))
    ])
    for name, value in ratio_fields:
        if not isinstance(value, (int, float)) or not 0 <= value <= 100:
            errors.append(f"{name}必须在0—100之间")

    plan_count = plan.get("计划开行列次", 0)
    fulfilled = direct.get("计划兑现列次", 0)
    stopped = direct.get("停运列次", 0)
    added = direct.get("加开列次", 0)
    actual = direct.get("实际开行列次", 0)

    c1 = fulfilled + stopped == plan_count
    c2 = fulfilled + added == actual
    checks.append({"name": "计划列次闭合", "passed": c1})
    checks.append({"name": "实际列次闭合", "passed": c2})
    if not c1:
        warnings.append("计划兑现列次+停运列次不等于计划开行列次")
    if not c2:
        warnings.append("计划兑现列次+加开列次不等于实际开行列次")

    plan_trains = {x.get("车次") for x in parsed_data.get("首末班车计划", []) if x.get("车次")}
    actual_trains = {x.get("车次") for x in parsed_data.get("首末班车执行明细", []) if x.get("车次")}
    train_match = plan_trains == actual_trains and len(plan_trains) > 0
    checks.append({"name": "首末班车次匹配", "passed": train_match})
    if not train_match:
        errors.append("首末班车计划与执行明细无法按车次完整匹配")

    exception_ids = [x.get("异常记录ID") for x in parsed_data.get("列次执行异常明细", [])]
    if len(exception_ids) != len(set(exception_ids)) or any(not x for x in exception_ids):
        errors.append("列次执行异常明细的异常记录ID必须非空且唯一")

    return {
        "is_valid": len(errors) == 0,
        "error_list": errors,
        "warn_list": warnings,
        "check_list": checks
    }

