def main(plan_data: dict, exec_data: dict) -> dict:
    from collections import Counter

    def rate_grade(value, good=99.0):
        if value is None:
            return "数据缺失"
        if value >= good:
            return "良好"
        if value >= good - 1:
            return "需关注"
        return "偏低"

    def online_grade(value):
        if value == 100:
            return "完全兑现"
        if value is not None and value >= 98:
            return "需关注"
        return "未充分兑现"

    def sec_text(seconds):
        seconds = int(seconds or 0)
        return f"{seconds // 60}分{seconds % 60:02d}秒"

    line_plan = plan_data["line_plan"]
    plan_map = {x["时段类型"]: x for x in plan_data["period_plan"]}
    direct = exec_data["direct"]
    exec_map = {x["时段类型"]: x for x in exec_data["period_exec"]}
    exceptions = exec_data.get("exceptions", [])

    period_rows = []
    facts = [
        {
            "topic": "exec", "priority": 3,
            "source_group": "业务系统直接指标", "source_field": "运行计划达成率",
            "fact": f"运行计划达成率{direct.get('运行计划达成率')}%",
            "value": direct.get("运行计划达成率"), "unit": "%"
        },
        {
            "topic": "exec", "priority": 3,
            "source_group": "业务系统直接指标", "source_field": "运行准点率",
            "fact": f"运行准点率{direct.get('运行准点率')}%",
            "value": direct.get("运行准点率"), "unit": "%"
        }
    ]

    for period in ["早高峰", "晚高峰", "平峰", "低谷"]:
        p = plan_map[period]
        e = exec_map[period]
        row = {
            "period": period,
            "plan_online": p.get("计划上线列数"),
            "actual_online": e.get("实际上线列数"),
            "online_rate": e.get("上线兑现率"),
            "online_grade": online_grade(e.get("上线兑现率")),
            "plan_gap_sec": p.get("计划行车间隔秒数"),
            "avg_gap_sec": e.get("实际平均行车间隔秒数"),
            "max_gap_sec": e.get("实际最大行车间隔秒数"),
            "avg_gap_dev_sec": e.get("平均间隔偏差秒数"),
            "max_gap_dev_sec": e.get("最大间隔偏差秒数")
        }
        period_rows.append(row)
        facts.append({
            "topic": "exec",
            "priority": 3 if e.get("上线兑现率", 100) < 100 else 1,
            "source_group": "分时段执行指标",
            "source_field": f"{period}.上线兑现率",
            "fact": (
                f"{period}计划上线{p.get('计划上线列数')}列、实际上线{e.get('实际上线列数')}列，"
                f"上线兑现率{e.get('上线兑现率')}%，最大间隔{sec_text(e.get('实际最大行车间隔秒数'))}"
            ),
            "value": e.get("上线兑现率"), "unit": "%"
        })

    type_count = Counter(x.get("异常类型", "未知") for x in exceptions)
    period_count = Counter(x.get("时段类型", "未知") for x in exceptions)
    warnings = []

    plan_count = line_plan.get("计划开行列次", 0)
    calc_rate = round(direct.get("计划兑现列次", 0) / plan_count * 100, 2) if plan_count else None
    if calc_rate is not None and abs(calc_rate - direct.get("运行计划达成率", 0)) > 0.1:
        warnings.append(f"运行计划达成率直传值{direct.get('运行计划达成率')}%与核验值{calc_rate}%不一致")

    return {
        "exec_result": {
            "topic": "exec",
            "status": rate_grade(direct.get("运行计划达成率")),
            "metrics": {
                "plan_trips": plan_count,
                "fulfilled_trips": direct.get("计划兑现列次"),
                "actual_trips": direct.get("实际开行列次"),
                "stopped_trips": direct.get("停运列次"),
                "added_trips": direct.get("加开列次"),
                "late_trips": direct.get("晚点列次"),
                "plan_rate": direct.get("运行计划达成率"),
                "punctual_rate": direct.get("运行准点率"),
                "periods": period_rows,
                "exception_by_type": dict(type_count),
                "exception_by_period": dict(period_count)
            },
            "warnings": warnings,
            "facts": facts
        }
    }

def main(plan_data: dict, load_data: dict) -> dict:
    def load_grade(value):
        if value is None:
            return "数据缺失"
        if value < 50:
            return "运力较充足"
        if value < 80:
            return "基本匹配"
        if value < 90:
            return "重点关注"
        if value < 100:
            return "局部偏紧"
        return "运力不足"

    def time_sec(text):
        h, m, s = [int(x) for x in text.split(":")]
        return h * 3600 + m * 60 + s

    def continuous_windows(rows, threshold=85.0):
        selected = [x for x in rows if x.get("满载率", 0) >= threshold]
        selected.sort(key=lambda x: (
            x.get("方向", ""), x.get("区段名称", ""),
            x.get("日期", ""), time_sec(x.get("开始时间", "00:00:00"))
        ))

        groups = []
        current = None
        for row in selected:
            key = (row.get("日期"), row.get("方向"), row.get("区段名称"), row.get("时段类型"))
            if (
                current
                and current["key"] == key
                and current["end_time"] == row.get("开始时间")
            ):
                current["end_time"] = row.get("结束时间")
                current["record_count"] += 1
                current["max_load_rate"] = max(current["max_load_rate"], row.get("满载率", 0))
            else:
                current = {
                    "key": key,
                    "date": row.get("日期"),
                    "direction": row.get("方向"),
                    "section": row.get("区段名称"),
                    "period": row.get("时段类型"),
                    "start_time": row.get("开始时间"),
                    "end_time": row.get("结束时间"),
                    "record_count": 1,
                    "max_load_rate": row.get("满载率", 0)
                }
                groups.append(current)

        for item in groups:
            item.pop("key", None)
            item["duration_min"] = item["record_count"] * 15
        return groups

    plan_map = {x["时段类型"]: x for x in plan_data["period_plan"]}
    period_exec = load_data["period_exec"]
    detail = load_data.get("section_detail", [])
    direct = load_data["direct"]

    period_rows = []
    facts = []
    for e in period_exec:
        period = e["时段类型"]
        p = plan_map[period]
        row = {
            "period": period,
            "plan_capacity": p.get("计划断面运力"),
            "actual_capacity": e.get("实际断面运力"),
            "max_flow": e.get("最大断面客流"),
            "max_load_rate": e.get("最大满载率"),
            "avg_load_rate": e.get("平均满载率"),
            "grade": load_grade(e.get("最大满载率"))
        }
        period_rows.append(row)
        facts.append({
            "topic": "load",
            "priority": 3 if e.get("最大满载率", 0) >= 90 else 2,
            "source_group": "分时段执行指标",
            "source_field": f"{period}.最大满载率",
            "fact": f"{period}最大满载率{e.get('最大满载率')}%，平均满载率{e.get('平均满载率')}%",
            "value": e.get("最大满载率"), "unit": "%"
        })

    max_section = max(detail, key=lambda x: x.get("满载率", -1)) if detail else {}
    windows = continuous_windows(detail, 85.0)
    if max_section:
        facts.append({
            "topic": "load", "priority": 3,
            "source_group": "断面满载率明细",
            "source_field": "最大满载率记录",
            "fact": (
                f"{max_section.get('时段类型')}{max_section.get('开始时间')}-{max_section.get('结束时间')}"
                f"{max_section.get('方向')}{max_section.get('区段名称')}满载率{max_section.get('满载率')}%，"
                f"折算小时断面客流{max_section.get('折算小时断面客流')}人/小时"
            ),
            "value": max_section.get("满载率"), "unit": "%"
        })

    for item in windows:
        if item["record_count"] >= 2:
            facts.append({
                "topic": "load", "priority": 3,
                "source_group": "断面满载率明细",
                "source_field": "连续高负荷窗口",
                "fact": (
                    f"{item['period']}{item['start_time']}-{item['end_time']}，"
                    f"{item['direction']}{item['section']}连续{item['duration_min']}分钟满载率不低于85%"
                ),
                "value": item["duration_min"], "unit": "分钟"
            })

    all_day_max = max((x.get("最大满载率", 0) for x in period_exec), default=None)
    return {
        "load_result": {
            "topic": "load",
            "status": load_grade(all_day_max),
            "metrics": {
                "all_day_avg_load": direct.get("全日平均满载率"),
                "all_day_max_load": all_day_max,
                "periods": period_rows,
                "max_section": max_section,
                "continuous_windows": windows
            },
            "warnings": [],
            "facts": facts
        }
    }

def main(trans_data: dict) -> dict:
    def transfer_grade(value):
        if value is None:
            return "数据缺失"
        return "良好" if value >= 95 else "需优化"

    def last_transfer_grade(value):
        if value == 100:
            return "完全保障"
        if value is not None and value >= 95:
            return "存在单点风险"
        return "保障不足"

    def sec_text(seconds):
        seconds = int(seconds or 0)
        return f"{seconds // 60}分{seconds % 60:02d}秒"

    m = trans_data["transfer_metrics"]
    mismatch = sorted(
        trans_data.get("mismatch_summary", []),
        key=lambda x: x.get("失配组合数", 0), reverse=True
    )
    last_mismatch = trans_data.get("last_mismatch", [])

    facts = [
        {
            "topic": "transfer", "priority": 3,
            "source_group": "换乘衔接指标", "source_field": "换乘衔接成功率",
            "fact": (
                f"计划换乘组合{m.get('计划换乘组合数')}组，成功{m.get('成功衔接组合数')}组，"
                f"换乘衔接成功率{m.get('换乘衔接成功率')}%"
            ),
            "value": m.get("换乘衔接成功率"), "unit": "%"
        },
        {
            "topic": "transfer", "priority": 2,
            "source_group": "换乘衔接指标", "source_field": "平均换乘等待秒数",
            "fact": (
                f"平均换乘等待{sec_text(m.get('平均换乘等待秒数'))}，"
                f"P95等待{sec_text(m.get('百分之九十五等待秒数'))}，"
                f"超过15分钟等待{m.get('超过十五分钟等待次数')}次"
            ),
            "value": m.get("平均换乘等待秒数"), "unit": "秒"
        },
        {
            "topic": "transfer", "priority": 3,
            "source_group": "换乘衔接指标", "source_field": "末班换乘保障率",
            "fact": (
                f"重点末班换乘{m.get('重点末班换乘组合数')}组，成功{m.get('成功末班换乘组合数')}组，"
                f"末班换乘保障率{m.get('末班换乘保障率')}%"
            ),
            "value": m.get("末班换乘保障率"), "unit": "%"
        }
    ]

    for row in last_mismatch:
        facts.append({
            "topic": "transfer", "priority": 3,
            "source_group": "重点末班换乘失配明细",
            "source_field": row.get("换乘车站", "未知站"),
            "fact": (
                f"{row.get('换乘车站')}重点末班换乘未衔接，"
                f"前序列车实际晚点{sec_text(row.get('前序列车实际晚点秒数'))}，"
                f"原因：{row.get('失配原因')}"
            ),
            "value": row.get("前序列车实际晚点秒数"), "unit": "秒"
        })

    expected_failed = m.get("计划换乘组合数", 0) - m.get("成功衔接组合数", 0)
    detail_failed = sum(x.get("失配组合数", 0) for x in mismatch)
    warnings = []
    if expected_failed != detail_failed:
        warnings.append(f"换乘失配汇总{expected_failed}组与站点明细{detail_failed}组不一致")

    return {
        "trans_result": {
            "topic": "transfer",
            "status": transfer_grade(m.get("换乘衔接成功率")),
            "metrics": {
                "station_count": m.get("换乘车站数"),
                "planned_pairs": m.get("计划换乘组合数"),
                "success_pairs": m.get("成功衔接组合数"),
                "success_rate": m.get("换乘衔接成功率"),
