def main(plan_data: dict, service_data: dict) -> dict:
    def parse_service_time(text):
        text = str(text or "")
        next_day = text.startswith("次日")
        text = text.replace("次日", "")
        h, m, s = [int(x) for x in text.split(":")]
        return h * 3600 + m * 60 + s + (86400 if next_day else 0)

    def sec_text(seconds):
        sign = "-" if seconds < 0 else ""
        seconds = abs(int(seconds))
        if seconds >= 3600:
            return f"{sign}{seconds // 3600}小时{seconds % 3600 // 60}分{seconds % 60:02d}秒"
        if seconds >= 60:
            return f"{sign}{seconds // 60}分{seconds % 60:02d}秒"
        return f"{sign}{seconds}秒"

    line_plan = plan_data["line_plan"]
    plan_rows = {x["车次"]: x for x in plan_data["first_last_plan"]}
    exec_rows = {x["车次"]: x for x in service_data["first_last_exec"]}
    direct = service_data["direct"]
    edge = service_data["edge_metrics"]
    external = service_data["external_metrics"]

    timing_rows = []
    facts = []
    for train_no, p in plan_rows.items():
        e = exec_rows.get(train_no, {})
        plan_time = p.get("计划发车时间")
        actual_time = e.get("实际时间")
        deviation = None
        if plan_time and actual_time:
            deviation = parse_service_time(actual_time) - parse_service_time(plan_time)
        timing_rows.append({
            "train_no": train_no,
            "type": p.get("类型"),
            "direction": p.get("方向"),
            "origin": p.get("始发车站"),
            "destination": p.get("终到车站"),
            "service_type": p.get("服务类型"),
            "plan_time": plan_time,
            "actual_time": actual_time,
            "deviation_sec": deviation
        })

    facts.extend([
        {
            "topic": "service", "priority": 3,
            "source_group": "业务系统直接指标", "source_field": "实际线路运营秒数",
            "fact": (
                f"计划线路运营时间{sec_text(line_plan.get('计划线路运营秒数', 0))}，"
                f"实际{sec_text(direct.get('实际线路运营秒数', 0))}，"
                f"偏差{sec_text(direct.get('运营时间偏差秒数', 0))}"
            ),
            "value": direct.get("实际线路运营秒数"), "unit": "秒"
        },
        {
            "topic": "service", "priority": 3,
            "source_group": "业务系统直接指标", "source_field": "末班车早发次数",
            "fact": f"末班车早发{direct.get('末班车早发次数')}次",
            "value": direct.get("末班车早发次数"), "unit": "次"
        },
        {
            "topic": "service", "priority": 2,
            "source_group": "运营边缘时段指标", "source_field": "边缘时段满载率",
            "fact": (
                f"首班后30分钟最大满载率{edge.get('首班后30分钟最大满载率')}%，"
                f"末班前1小时最大满载率{edge.get('末班前1小时最大满载率')}%"
            ),
            "value": edge.get("末班前1小时最大满载率"), "unit": "%"
        },
        {
            "topic": "service", "priority": 3,
            "source_group": "外部交通衔接指标", "source_field": "交通衔接覆盖率",
            "fact": (
                f"重点外部交通到发需求{external.get('重点到发需求组数')}组，"
                f"已覆盖{external.get('已覆盖组数')}组，覆盖率{external.get('交通衔接覆盖率')}%"
            ),
            "value": external.get("交通衔接覆盖率"), "unit": "%"
        }
    ])

    coverage = external.get("交通衔接覆盖率")
    edge_low = max(
        edge.get("首班后30分钟最大满载率", 100),
        edge.get("末班前1小时最大满载率", 100)
    ) < 50
    if direct.get("末班车早发次数", 0) > 0:
        status = "需整改"
    elif coverage is not None and coverage >= 95 and edge_low:
        status = "基本合理"
    else:
        status = "需进一步评估"

    return {
        "service_result": {
            "topic": "service",
            "status": status,
            "metrics": {
                "plan_start": line_plan.get("计划线路运营开始时间"),
                "plan_end": line_plan.get("计划线路运营结束时间"),
                "plan_duration_sec": line_plan.get("计划线路运营秒数"),
                "actual_start": direct.get("实际线路运营开始时间"),
                "actual_end": direct.get("实际线路运营结束时间"),
                "actual_duration_sec": direct.get("实际线路运营秒数"),
                "duration_dev_sec": direct.get("运营时间偏差秒数"),
                "last_early_count": direct.get("末班车早发次数"),
                "timing_rows": timing_rows,
                "edge_metrics": edge,
                "external_metrics": external
            },
            "warnings": [],
            "facts": facts
        }
    }

def main(
    plan_result: dict,
    exec_result: dict,
    load_result: dict,
    trans_result: dict,
    service_result: dict,
    ext_results=None
) -> dict:
    import json

    def compact(value, depth=0):
        """限制模型专题包大小；完整结果仍保留在metric_result。"""
        if depth > 6:
            return None
        if isinstance(value, dict):
            return {str(k): compact(v, depth + 1) for k, v in value.items() if k != "facts"}
        if isinstance(value, list):
            return [compact(x, depth + 1) for x in value[:20]]
        if isinstance(value, str):
            return value[:300]
        return value

    ext_results = ext_results or []
    metric_result = {
        "plan": plan_result,
        "exec": exec_result,
        "load": load_result,
        "transfer": trans_result,
        "service": service_result,
        "extensions": ext_results
    }

    topic_packets = {
        "exec": compact({"plan": plan_result, "exec": exec_result}),
        "load": compact(load_result),
        "transfer": compact(trans_result),
        "service": compact(service_result)
    }

    # 这里只提示长度；真正调用模型前仍需按平台计数方式检查。
    for topic, packet in topic_packets.items():
        packet["serialized_length"] = len(json.dumps(packet, ensure_ascii=False))

    return {
        "metric_result": metric_result,
        "topic_packets": topic_packets
    }

def main(metric_result: dict) -> dict:
    prefix = {
        "exec": "E-EXEC",
        "load": "E-LOAD",
        "transfer": "E-TRANS",
        "service": "E-SERVICE"
    }
    collected = {k: [] for k in prefix}
    seen = set()

    for result_name in ["plan", "exec", "load", "transfer", "service"]:
        result = metric_result.get(result_name, {})
        for fact in result.get("facts", []):
            topic = fact.get("topic", "exec")
            if topic not in collected:
                continue
            dedupe_key = (
                topic,
                fact.get("source_group"),
                fact.get("source_field"),
                fact.get("fact")
            )
            if dedupe_key in seen:
                continue
            seen.add(dedupe_key)
            collected[topic].append(dict(fact))

    evidence_pool = []
    evidence_by_topic = {}
    for topic, rows in collected.items():
        rows.sort(key=lambda x: x.get("priority", 1), reverse=True)
        numbered = []
        for index, row in enumerate(rows, 1):
            item = dict(row)
            item["evidence_id"] = f"{prefix[topic]}-{index:03d}"
            item["source_type"] = "业务系统直传或代码确定性整理"
            item["fact"] = str(item.get("fact", ""))[:120]
            numbered.append(item)
            evidence_pool.append(item)
        # 单个专题模型最多接收12条；完整证据仍在evidence_pool。
        evidence_by_topic[topic] = numbered[:12]

    return {
        "evidence_pool": evidence_pool,
        "evidence_by_topic": evidence_by_topic
    }

def main(metric_result: dict, evidence_by_topic: dict) -> dict:
    issues = []

    def evidence_ids(topic, limit=3):
        return [x["evidence_id"] for x in evidence_by_topic.get(topic, [])[:limit]]

    def add(topic, title, level, conditions, suggestion_scope):
        issues.append({
            "candidate_id": f"CAND-{len(issues) + 1:03d}",
            "topic": topic,
            "title": title,
            "level": level,
            "conditions": conditions,
            "suggestion_scope": suggestion_scope,
            "evidence_ids": evidence_ids(topic)
        })

    plan = metric_result.get("plan", {})
    if plan.get("status") != "完整":
        add("exec", "运行图计划参数存在未闭合项", "高", plan.get("warnings", []), "核查计划参数及车辆配置")

    exec_m = metric_result.get("exec", {}).get("metrics", {})
    if exec_m.get("plan_rate", 100) < 99:
        add("exec", "运行计划达成率偏低", "高", [f"达成率{exec_m.get('plan_rate')}%"], "核查停运及未兑现列次")
    if exec_m.get("punctual_rate", 100) < 99:
        add("exec", "运行准点率偏低", "高", [f"准点率{exec_m.get('punctual_rate')}%"], "核查晚点列次及影响时段")

    for row in exec_m.get("periods", []):
        if row.get("online_rate", 100) < 100:
            add(
                "exec",
                f"{row.get('period')}上线列车未完全兑现",
                "高" if row.get("online_rate", 100) < 99 else "中",
                [f"计划{row.get('plan_online')}列、实际{row.get('actual_online')}列、兑现率{row.get('online_rate')}%"],
                "恢复计划上线列数"
            )
        if row.get("max_gap_dev_sec", 0) >= 60:
            add(
                "exec", f"{row.get('period')}出现明显大间隔", "高",
                [f"最大间隔偏差{row.get('max_gap_dev_sec')}秒"],
                "控制行车间隔并核查关联停运或晚点"
            )

    load_m = metric_result.get("load", {}).get("metrics", {})
    for row in load_m.get("periods", []):
        rate = row.get("max_load_rate", 0)
        if rate >= 90:
            add(
                "load", f"{row.get('period')}重点区段运力偏紧", "高",
                [f"最大满载率{rate}%"], "优先恢复计划运力并监测重点区段"
            )
        elif rate >= 80:
            add(
                "load", f"{row.get('period')}满载率进入关注区间", "中",
                [f"最大满载率{rate}%"], "持续监测客流和实际间隔"
            )

    for window in load_m.get("continuous_windows", []):
        if window.get("duration_min", 0) >= 30:
            add(
                "load", "重点区段连续高负荷", "高",
                [f"{window.get('section')}连续{window.get('duration_min')}分钟不低于85%"],
                "联动分析时段运力和大间隔"
            )

    trans_m = metric_result.get("transfer", {}).get("metrics", {})
    if trans_m.get("success_rate", 100) < 95:
        add("transfer", "整体换乘衔接效果需优化", "中", [f"成功率{trans_m.get('success_rate')}%"], "核查失配站点和接续时刻")
    if trans_m.get("last_success_rate", 100) < 100:
        add("transfer", "重点末班换乘存在失配", "高", [f"末班换乘保障率{trans_m.get('last_success_rate')}%"], "评估时刻微调、协同等待和预警")

    service_m = metric_result.get("service", {}).get("metrics", {})
    if service_m.get("last_early_count", 0) > 0:
        add("service", "末班车存在早发", "高", [f"早发{service_m.get('last_early_count')}次"], "立即核查末班车执行")
    coverage = service_m.get("external_metrics", {}).get("交通衔接覆盖率", 100)
    if coverage < 95:
        add("service", "外部交通衔接覆盖不足", "中", [f"覆盖率{coverage}%"], "评估首末班或临时延时方案")

    issues_by_topic = {k: [] for k in ["exec", "load", "transfer", "service"]}
    for item in issues:
        issues_by_topic[item["topic"]].append(item)

    return {
        "issue_cands": issues,
        "issues_by_topic": issues_by_topic
    }

def main(
    exec_md,
    load_md,
    trans_md,
    service_md,
    evidence_pool: list,
    topic_packets: dict
) -> dict:
    import json
    import re

    def clean_markdown(value):
        text = str(value or "").strip()
        if text.startswith("```"):
            text = re.sub(r"^```(?:markdown|md)?\s*", "", text)
            text = re.sub(r"\s*```$", "", text)
        return text.strip()

    def numeric_tokens(value):
        text = json.dumps(value, ensure_ascii=False)
        return set(re.findall(r"(?<![A-Za-z])\d+(?:\.\d+)?", text))

    raw = {
        "exec": exec_md,
        "load": load_md,
        "transfer": trans_md,
        "service": service_md
    }
    expected_headings = {
        "exec": "## 二、运行图兑现效果",
        "load": "## 三、运力客流匹配效果",
        "transfer": "## 四、换乘衔接效果",
        "service": "## 五、运营时间与首末班车合理性"
    }
    max_lengths = {"exec": 8000, "load": 8000, "transfer": 7000, "service": 7000}
    chapters = {}
    reviews = []
    warnings = []
    hard_errors = []

    for topic, value in raw.items():
        text = clean_markdown(value)
        if not text:
            hard_errors.append(f"{topic}章节正文为空")
            continue
        if not text.startswith(expected_headings[topic]):
            hard_errors.append(f"{topic}章节标题不正确，应以“{expected_headings[topic]}”开头")
        if len(text) > max_lengths[topic]:
            hard_errors.append(f"{topic}章节超过{max_lengths[topic]}字符")

        visible_ids = re.findall(r"E-(?:EXEC|LOAD|TRANS|SERVICE)-\d{3}", text)
        if visible_ids:
            hard_errors.append(f"{topic}章节不应展示内部证据ID：{sorted(set(visible_ids))}")

        # 数字检查采用提示级别，避免把章节编号误判为业务数字。
        allowed_nums = numeric_tokens(topic_packets.get(topic, {}))
        allowed_nums |= numeric_tokens([x for x in evidence_pool if x.get("topic") == topic])
        output_nums = numeric_tokens(text)
        unknown_nums = sorted(x for x in output_nums - allowed_nums if float(x) > 20)
        if unknown_nums:
            warnings.append(f"{topic}章节出现需复核数字：{unknown_nums[:10]}")

        marker = "### 专题结论"
        if marker in text:
            topic_summary = text.split(marker, 1)[1].strip()[:600]
        else:
            topic_summary = text[-600:]
            warnings.append(f"{topic}章节缺少“### 专题结论”，已截取末尾文字作为摘要")

        chapters[topic] = text
        reviews.append({
            "topic": topic,
            "heading": expected_headings[topic],
            "content_length": len(text),
            "topic_summary": topic_summary
        })

    # 综合模型仍需内部事实依据，但不依赖正文显式引用编号。
    topic_order = ["exec", "load", "transfer", "service"]
    ranked = sorted(
        evidence_pool,
        key=lambda x: (-int(x.get("priority", 0)), str(x.get("evidence_id", "")))
    )
    summary_evidence = []
    selected_ids = set()
    for topic in topic_order:
        topic_items = [x for x in ranked if x.get("topic") == topic][:3]
        for item in topic_items:
            item_id = item.get("evidence_id")
            if item_id not in selected_ids:
                summary_evidence.append(item)
                selected_ids.add(item_id)
    for item in ranked:
        if len(summary_evidence) >= 12:
            break
        item_id = item.get("evidence_id")
        if item_id not in selected_ids:
            summary_evidence.append(item)
            selected_ids.add(item_id)

    return {
        "chapter_texts": chapters,
        "chapter_review": reviews,
        "summary_evidence": summary_evidence,
        "model_warns": warnings + hard_errors,
        "needs_retry": len(hard_errors) > 0
    }
